function header(){return `<header class="site-header"><div class="header-inner">${logo()}<button class="menu-button" data-action="menu" aria-label="${state.lang==='en'?'Toggle navigation':'開啟或關閉選單'}" aria-controls="primary-nav" aria-expanded="${state.menu}">${I(state.menu?'close':'menu',24)}</button><nav id="primary-nav" class="main-nav ${state.menu?'open':''}" aria-label="${state.lang==='en'?'Main navigation':'主要導覽'}">${navKeys.map((k,i)=>`<a href="#${k}" class="${state.page===k?'active':''}" ${state.page===k?'aria-current="page"':''}>${T().nav[i]}</a>`).join('')}</nav><div class="header-tools"><button data-action="search" aria-label="${state.lang==='en'?'Search the map':'搜尋地圖'}">${I('search',21)}</button><button class="language" data-action="language">${I('globe',18)} ${state.lang==='en'?'繁':'EN'}</button></div></div></header>`}
