let revealObserver;
function setupPageMotion(){revealObserver?.disconnect();if(reducedMotion()||!('IntersectionObserver' in window))return;revealObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target)}},{threshold:.08});document.querySelectorAll('.home-categories>.section-head,.home-feature,.home-stories>.section-head').forEach(el=>{el.classList.add('section-reveal');revealObserver.observe(el)})}
function layout(body,{showFooter=true}={}){const oldStep=$('#contribution-form')?.dataset.step;app.innerHTML=`${header()}${body}${showFooter?footer():''}<button class="back-to-top" data-action="back-to-top" aria-label="${state.lang==='en'?'Back to top':'回到頂部'}" title="${state.lang==='en'?'Back to top':'回到頂部'}">${I('arrow',20)}</button>`;updateBackToTop();setupPageMotion();const form=$('#contribution-form');if(oldStep&&form&&oldStep!==form.dataset.step&&!reducedMotion())form.animate([{opacity:.5,transform:'translateY(6px)'},{opacity:1,transform:'none'}],{duration:200,easing:'cubic-bezier(.23,1,.32,1)'})}
