function home(){const categories=state.site.categories?.length?state.site.categories:[{key:'食',titleZh:'食',titleEn:'Eat',subtitleZh:'品味在地風味',subtitleEn:'Taste local flavours',image:'assets/flat-cafe.webp'},{key:'買',titleZh:'買',titleEn:'Shop',subtitleZh:'發掘特色好物',subtitleEn:'Choose thoughtful goods',image:'assets/flat-shop.webp'},{key:'修',titleZh:'修',titleEn:'Repair',subtitleZh:'延續物件的生命',subtitleEn:'Give objects another life',image:'assets/flat-afa.webp'},{key:'去',titleZh:'去',titleEn:'Explore',subtitleZh:'探索澳門之美',subtitleEn:'Discover another Macau',image:'assets/flat-waterfront.webp'},{key:'學',titleZh:'學',titleEn:'Learn',subtitleZh:'從自然與社區學習',subtitleEn:'Learn from place and nature',image:'assets/flat-learn.webp'},{key:'參與',titleZh:'參與',titleEn:'Join',subtitleZh:'一起創造改變',subtitleEn:'Take part in local change',image:'assets/flat-youth.webp'}];const hot=state.site[state.lang==='en'?'hotSearchesEn':'hotSearchesZh']||[];const featured=articleFor(state.site.featureArticleId),featuredPlace=!featured&&state.places.find(p=>p.id.startsWith('catalog-')&&p.img&&p.desc);const storyArticles=(state.site.storyArticleIds||[]).map(articleFor).filter(Boolean);layout(`<main class="home-page"><section class="home-hero"><div class="hero-copy"><h1>${esc(S('heroTitle')).replace(/\n/g,'<br>')}</h1><form class="editorial-search" data-search-form><span>${I('search')}</span><input name="q" aria-label="${T().search}" placeholder="${esc(state.site[state.lang==='en'?'searchPlaceholderEn':'searchPlaceholderZh']||T().search)}"><button aria-label="${state.lang==='en'?'Search':'搜尋'}">${I('search',19)}</button></form><div class="hot"><span>${state.lang==='en'?'Popular:':'熱門搜尋：'}</span>${hot.map(x=>`<button data-quick="${esc(x)}">${esc(x)}</button>`).join('')}</div></div><a class="hero-visual" href="${articleFor(state.site.heroArticleId)?goArticle(state.site.heroArticleId):'#map'}"><img src="${esc(imagePath(state.site.heroImage))}" alt=""><span>${state.lang==='en'?'Explore Macau':'探索澳門'} ${I('arrow')}</span></a></section><section class="home-categories" aria-labelledby="category-title"><div class="section-head"><div><h2 id="category-title">${state.lang==='en'?'Categories':'探索分類'}</h2></div><a href="#map">${T().explore} ${I('arrow',16)}</a></div><div class="category-gallery">${categories.map((c,i)=>`<a href="#map?cat=${encodeURIComponent(c.key)}" class="category-tile" data-category="${esc(c.key)}" style="--category-color:${mapCategories[c.key]?.color||'var(--green)'}"><img src="${esc(imagePath(c.image))}" alt=""><span class="category-shade"></span><span class="category-copy"><strong>${esc(state.lang==='en'?c.titleEn:c.titleZh)}</strong></span><i>${I('arrow',16)}</i></a>`).join('')}</div></section>${featured||featuredPlace?`<section class="home-feature"><div class="feature-photo"><img src="${esc(imagePath(featuredPlace?featuredPlace.img:state.site.featureImage))}" alt=""></div><div class="feature-copy"><h2>${esc(featuredPlace?loc(featuredPlace,'name','en'):S('featureTitle'))}</h2><p>${esc(featuredPlace?loc(featuredPlace,'desc','desc_en'):S('featureBody'))}</p><a href="${featuredPlace?`#place/${encodeURIComponent(featuredPlace.id)}`:goArticle(featured.id)}">${featuredPlace?(state.lang==='en'?'Discover this place':'認識這個地方'):T().read} ${I('arrow',17)}</a></div></section>`:''}${state.articles.length?`<section class="home-stories"><div class="section-head"><div><h2>${state.lang==='en'?'Stories':'人物故事'}</h2></div><a href="#stories">${T().more} ${I('arrow',16)}</a></div><div class="story-strip">${storyArticles.map((a,i)=>storyHorizontal(a,i)).join('')||state.articles.slice(0,3).map((a,i)=>storyHorizontal(a,i)).join('')}</div></section>`:''}</main>`)}
function articleTone(a){return mapCategories[state.places.find(p=>p.id===a.place_id)?.cat]?.color||'var(--accent-600)'}
